import {escapeHTML as e} from './core.js?v=20261027c';
export function accountPage(space){const i=space.info();return `<div class="page-heading"><div><div class="eyebrow">SHARED STUDY SPACE</div><h1>ข้อมูลและการซิงก์</h1><p>พื้นที่กลางเดียวกันทุกเบราว์เซอร์ ทุกเครื่อง ไม่ต้องเข้าสู่ระบบ</p></div></div><section class="panel account-panel"><div class="notebook-status"><span class="status-dot"></span><strong data-sync-status>${e(i.status)}</strong></div><h2>เปิดเว็บนี้ก็เห็นงานชุดเดียวกัน</h2><p>โน้ต รูปภาพ และความคืบหน้าเก็บในพื้นที่กลางบน Supabase เมื่อแก้ไขหรือกลับมาเปิดหน้านี้ ระบบจะซิงก์ข้อมูลให้ และตรวจข้อมูลใหม่ทุก 5 วินาทีขณะที่เปิดแอปอยู่</p><p class="quiet-note">พื้นที่นี้เปิดให้ผู้ที่เข้าถึงเว็บอ่าน แก้ไข และลบงานร่วมกันได้</p><div class="button-row"><button class="button primary" data-action="account-sync">บันทึกและซิงก์ตอนนี้</button><button class="button secondary" data-action="account-reload">ลองเชื่อมต่ออีกครั้ง</button></div><p>ซิงก์ล่าสุด: <span id="last-sync">${i.lastSync?e(new Date(i.lastSync).toLocaleString('th-TH')):'ยังไม่มี'}</span></p><p id="account-message" role="status" class="account-message"></p><div id="sync-conflict" ${i.conflict?'':'hidden'} class="notice danger"><h3>มีการแก้ไขพร้อมกันจากอีกเครื่อง</h3><p>เลือกฉบับที่จะใช้ ระบบจะเก็บสำเนาทั้งสองฉบับก่อนแทนที่</p><div class="button-row"><button class="button secondary" data-action="account-remote">ใช้ฉบับคลาวด์</button><button class="button secondary" data-action="account-local">ใช้ฉบับเครื่องนี้</button></div></div></section><section class="panel"><h2>โน้ตจากระบบเดิม</h2><p>เปิดเว็บรุ่นใหม่นี้หนึ่งครั้งในเบราว์เซอร์เดิมที่เคยจด ระบบจะคัดลอกโน้ตและรูปเดิมเข้าพื้นที่กลางอัตโนมัติ จากนั้นทุกเครื่องจะเห็นร่วมกัน ต้นฉบับในพื้นที่เดิมยังเก็บไว้</p><p>หากนำเข้าไม่สำเร็จ ระบบจะแจ้งด้านบน ให้ตรวจอินเทอร์เน็ตแล้วกดลองเชื่อมต่ออีกครั้ง</p><a class="button secondary" href="#settings">ตั้งค่าและสำรองข้อมูล</a></section>`;}
export async function accountAction(action,space,render,toast){
 const say=text=>{const msg=document.getElementById('account-message');if(msg)msg.textContent=text;};
 try{
  if(action==='account-reload'){location.reload();return;}
  if(action==='account-sync'){await space.sync();say(space.info().status);}
  if(['account-remote','account-local'].includes(action)&&confirm('ยืนยันใช้ฉบับที่เลือก? อีกฉบับจะเก็บเป็นสำเนากู้คืน')){await space.resolve(action==='account-local');render();}
 }catch(err){const text=err.message||'ดำเนินการไม่สำเร็จ';say(text);toast(text);}
}
